package com.vandorlabs.neoforge.builders;
import com.mojang.serialization.MapCodec;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.BlockHitResult;
public final class NativeBuilderCoreBlock extends BaseEntityBlock {
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;public static final BooleanProperty FORMED=BooleanProperty.create("formed");public final NativeBuilderDesigns.Design design;
 NativeBuilderCoreBlock(NativeBuilderDesigns.Design design,Properties p){super(p);this.design=design;registerDefaultState(stateDefinition.any().setValue(FACING,Direction.NORTH).setValue(FORMED,false));}
 @Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){b.add(FACING,FORMED);}@Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,c.getHorizontalDirection().getOpposite());}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new NativeBuilderEntity(p,s);}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> t){return l.isClientSide?null:createTickerHelper(t,NativeBuilderBindings.ENTITY,NativeBuilderEntity::tick);}
 @Override protected ItemInteractionResult useItemOn(ItemStack stack,BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){return NativeBuilderBindings.interact(player,level,pos,hand)?ItemInteractionResult.SUCCESS:ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;}
 @Override protected InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,BlockHitResult hit){return NativeBuilderBindings.interact(player,level,pos,InteractionHand.MAIN_HAND)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.PASS;}
 @Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos f,boolean m){if(!l.isClientSide&&l.getBlockEntity(p) instanceof NativeBuilderEntity owner)owner.samplePower();}
 @Override protected java.util.List<ItemStack> getDrops(BlockState state,net.minecraft.world.level.storage.loot.LootParams.Builder context){var raw=context.getOptionalParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.BLOCK_ENTITY);if(state.getValue(FORMED)||raw instanceof NativeBuilderEntity owner&&owner.ownsRecovery())return java.util.List.of();return super.getDrops(state,context);}

 @Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){super.onRemove(s,l,p,next,moving);}
}
